-- Plan 54: upgrade the three established banners in place and add the
-- alternate procedural palettes as separate, independently ownable items.
-- Existing cosmetic ids, prices, ownership rows and equipped loadouts remain intact.

UPDATE cosmetic_items
SET asset = CASE id
  WHEN 'banner-lingayen-sunset' THEN '{"style":"procedural","generator":"sunset","palette":"golden","colors":["#2b2a5c","#c8577a","#f6a85a","#ffe2a0","#3c3a6b","#141634"],"fallback":{"colors":["#2b2a5c","#c8577a"],"angle":135,"pattern":"sun"},"angle":135,"pattern":"sun"}'::jsonb
  WHEN 'banner-hundred-islands' THEN '{"style":"procedural","generator":"islands","palette":"midday","colors":["#0a3a5a","#1792ad","#73dccd","#efdcae","#2c6637","#68a952"],"fallback":{"colors":["#0a3a5a","#1792ad"],"angle":160,"pattern":"islands"},"angle":160,"pattern":"islands"}'::jsonb
  WHEN 'banner-bangus-festival' THEN '{"style":"procedural","generator":"bangus","palette":"silver","colors":["#0f5e72","#06283a","#2d4c63","#dfe9ee","#9ee7f0"],"fallback":{"colors":["#0f5e72","#06283a"],"angle":150,"pattern":"waves"},"angle":150,"pattern":"waves"}'::jsonb
END
WHERE id IN ('banner-lingayen-sunset','banner-hundred-islands','banner-bangus-festival');

ON CONFLICT(id) DO NOTHING;
